import React,{useEffect,useMemo,useState}from'react';
import{Routes,Route,Link,useNavigate,useParams,useLocation}from'react-router-dom';
import{api,user,session,logout}from'./api.js';

const fmt=v=>v?new Intl.DateTimeFormat('es-AR',{dateStyle:'medium',timeStyle:'short',timeZone:'America/Argentina/Buenos_Aires'}).format(new Date(v)):'-';
const err=e=>e.response?.data?.error||'No se pudo completar la acción.';
const eventText=e=>{const d=e?.data||{};if(e?.event_type==='ladder_swap')return `Ganaste una posición: #${d.from} → #${d.to}.`;if(e?.event_type==='position_penalty')return 'Penalización de posición/deuda aplicada.';if(e?.event_type==='promotion')return `Ascenso: ${d.from}ª → ${d.to}ª.`;if(e?.event_type==='relegation')return `Descenso: ${d.from}ª → ${d.to}ª.`;if(e?.event_type==='assignment_created')return 'La rueda asignó un nuevo rival.';if(e?.event_type==='schedule_proposed')return 'Se registró una nueva propuesta de fecha y lugar.';if(e?.event_type==='schedule_accepted')return 'Fecha, hora y lugar quedaron confirmados.';if(e?.event_type==='result_submitted')return 'Se cargó una versión del resultado.';if(e?.event_type==='result_revised')return 'Se corrigió la versión del resultado.';if(e?.event_type==='match_confirmed')return 'El resultado quedó oficial.';return 'LA RED registró un cambio competitivo.';};
function Layout({children,transparent=false}){const u=user();const initials=[u?.first_name,u?.last_name].filter(Boolean).map(v=>String(v).trim()[0]).join('').slice(0,2).toUpperCase()||'LR';return <div className="app"><header className={`header ${transparent?'header-transparent':''}`}><Link className="brand" to="/"><span>LA RED</span><small>PÁDEL · SAN PEDRO</small></Link><nav className="nav"><Link to="/">Inicio</Link><Link to="/ranking">Ranking</Link><Link to="/proximos">Próximos</Link>{u&&<Link to="/liga">Mi liga</Link>}{u&&<Link to="/pareja">Pareja</Link>}{u&&<Link to="/notificaciones">Avisos</Link>}{u&&<Link to="/cuenta">Cuenta</Link>}{u?.role==='admin'&&<Link to="/admin">Admin</Link>}</nav><div className="header-actions">{u?<><Link className="header-profile" to="/cuenta"><span className="header-avatar">{initials}</span><span className="header-profile-copy"><small>MI CUENTA</small><strong>{u.first_name||'Jugador'}</strong></span></Link><button className="header-exit" onClick={logout}><span>Salir</span><b>↗</b></button></>:<><Link className="header-link" to="/ingresar">Ingresar</Link><Link className="header-create" to="/ingresar?registro=1">Crear cuenta</Link></>}</div></header>{children}</div>}
function Notice({n}){return n?<div className={`notice ${n.type||''}`}>{n.text}</div>:null;}
function Home(){const[up,setUp]=useState([]),[records,setRecords]=useState([]),[recent,setRecent]=useState([]),[rows,setRows]=useState([]),[gender,setGender]=useState('masculino');useEffect(()=>{api.get('/upcoming').then(r=>setUp(r.data||[])).catch(()=>setUp([]));api.get('/records').then(r=>setRecords(r.data||[])).catch(()=>setRecords([]));api.get('/results/recent').then(r=>setRecent(r.data||[])).catch(()=>setRecent([]));api.get('/ranking').then(r=>setRows(r.data||[])).catch(()=>setRows([]));},[]);const top=useMemo(()=>rows.filter(r=>r.slug===gender).sort((a,b)=>Number(a.number)-Number(b.number)||Number(a.position)-Number(b.position)).slice(0,10),[rows,gender]);return <Layout transparent><main><section className="home-hero"><div className="hero-photo"/><div className="hero-overlay"/><div className="hero-top-tags"><span>LA RED</span><span>LIGA DE PÁDEL</span><span>SAN PEDRO</span></div><div className="hero-layout"><div className="hero-copy"><div className="hero-mini">LA RED PÁDEL · SAN PEDRO</div><h1>La Red<span>PÁDEL · SAN PEDRO</span></h1><p>Una liga continua por parejas, automática y transparente. La posición se conquista en cancha.</p><div className="hero-buttons"><Link className="button button-green" to="/ranking">VER RANKING</Link><Link className="button button-outline" to="/ingresar?registro=1">QUIERO JUGAR</Link></div></div><aside className="top-card"><div className="top-card-header"><h2>TOP 10</h2><select value={gender} onChange={e=>setGender(e.target.value)}><option value="masculino">Masculino</option><option value="femenino">Femenino</option></select></div><div className="top-list">{top.length===0&&<div className="top-empty">Todavía no hay parejas en este ranking.</div>}{top.map((r,i)=><Link to={`/parejas/${r.pair_id}`} className="top-row" key={r.pair_id}><span className={`top-position ${i===0?'first':''}`}>{i+1}</span><div className="top-player"><strong>{r.players}</strong><small>{r.number}ª · posición #{r.position}</small></div><span className="top-elo">{r.elo}</span></Link>)}</div><Link className="top-link" to="/ranking">Ver ranking completo <span>→</span></Link></aside></div><div className="feature-grid"><article className="feature-card"><div className="feature-icon blue">◎</div><h3>RUEDA AUTOMÁTICA</h3><p>LA RED te asigna rival sin que tengas que buscarlo.</p></article><article className="feature-card"><div className="feature-icon green">◷</div><h3>COORDINACIÓN</h3><p>Fecha, hora y cancha quedan registradas y confirmadas.</p></article><article className="feature-card"><div className="feature-icon blue">▥</div><h3>RESULTADOS</h3><p>Cargá, confirmá y dejá que el motor aplique el movimiento.</p></article><article className="feature-card"><div className="feature-icon green">◉</div><h3>LA RED</h3><p>Ranking, próximos partidos, perfiles y récords públicos.</p></article></div></section><section className="home-rules"><div className="rules-title"><span>CÓMO FUNCIONA</span><h2>Jugá. Ganá.<br/>Subí.</h2></div><div className="rules"><article><strong>01</strong><h3>Formá tu pareja</h3><p>Ambos aceptan la invitación y LA RED determina la categoría competitiva correspondiente.</p></article><article><strong>02</strong><h3>Recibí tu rival</h3><p>La rueda asigna automáticamente un partido y abre un plazo máximo de 30 días para jugar y cargar resultado.</p></article><article><strong>03</strong><h3>Conquistá posiciones</h3><p>Si una pareja de abajo vence a una de arriba, intercambian lugares. El ELO acompaña; no gobierna.</p></article></div></section><section className="home-content"><div className="home-section-title"><span className="section-label">CARTELERA</span><h2>Esta semana en LA RED</h2></div><div className="grid3">{up.slice(0,6).map(m=><article className="card" key={m.id}><span className="eyebrow">{m.category_number}ª · {m.slug}</span><h3>{m.pair_a}<br/>vs.<br/>{m.pair_b}</h3><p>{fmt(m.scheduled_at)} · {m.venue_name}</p></article>)}{!up.length&&<div className="empty">Todavía no hay partidos públicos confirmados.</div>}</div></section><section className="home-content"><div className="home-section-title"><span className="section-label">ÚLTIMOS PARTIDOS</span><h2>Resultados recientes</h2></div><div className="grid3">{recent.slice(0,6).map(m=><article className="card" key={m.id}><span className="eyebrow">{m.category_number}ª · {m.slug}</span><h3>{m.pair_a}<br/>vs.<br/>{m.pair_b}</h3><p>{m.result_type==='injury_abandonment'?'Lesión / abandono':m.result_type==='dissolution_forfeit'?'Forfeit por disolución':'Resultado oficial'} · {fmt(m.played_at)}</p></article>)}{!recent.length&&<div className="empty">Todavía no hay resultados oficiales.</div>}</div></section><section className="home-content records-section"><div className="home-section-title"><span className="section-label">PRIMERA</span><h2>Récords históricos</h2></div><div className="grid2">{records.map(r=><article className="record-card" key={r.slug}><span>PRIMERA {r.slug?.toUpperCase()}</span><strong>{r.pair_name||'Sin récord todavía'}</strong><b>{r.elo?`ELO ${r.elo}`:'—'}</b><small>{r.elo?`${r.defenses} defensas`:'Aparecerá cuando exista actividad oficial.'}</small></article>)}</div></section><footer className="footer"><div><strong>LA RED PÁDEL · SAN PEDRO</strong><span>Más pádel. Más comunidad.</span></div><div className="footer-links"><Link to="/ranking">Ranking</Link><Link to="/proximos">Próximos</Link><Link to="/instalar">Instalar app</Link></div></footer></main></Layout>}
function Auth(){const nav=useNavigate();const location=useLocation();const registerMode=new URLSearchParams(location.search).get('registro')==='1';const[mode,setMode]=useState(registerMode?'register':'login'),[form,setForm]=useState({gender:'male',legalAcceptances:{}}),[acceptedLegal,setAcceptedLegal]=useState(false),[notice,setNotice]=useState(),[loading,setLoading]=useState(false);useEffect(()=>{api.get('/legal/versions').then(r=>setForm(f=>({...f,legalAcceptances:r.data})))},[]);useEffect(()=>{setMode(registerMode?'register':'login');setNotice();},[registerMode]);async function submit(e){e.preventDefault();if(mode==='register'&&!acceptedLegal){setNotice({type:'error',text:'Debés aceptar los documentos y confirmar que sos mayor de 18 años.'});return;}if(mode==='register'&&(!form.dniFront||!form.dniBack)){setNotice({type:'error',text:'Tenés que adjuntar una foto del frente y otra del dorso del DNI.'});return;}try{setLoading(true);setNotice();let response;if(mode==='register'){const data=new FormData();for(const key of ['firstName','lastName','phone','gender','dni','password'])data.append(key,form[key]||'');data.append('legalAcceptances',JSON.stringify(form.legalAcceptances||{}));data.append('dniFront',form.dniFront);data.append('dniBack',form.dniBack);response=await api.post('/auth/register',data);}else response=await api.post('/auth/login',form);session(response.data);nav('/liga');}catch(e){setNotice({type:'error',text:err(e)});}finally{setLoading(false)}}return <Layout><main className="center"><section className="auth card"><span className="eyebrow">LA RED</span><h1>{mode==='login'?'Ingresar':'Crear cuenta'}</h1><form onSubmit={submit}>{mode==='register'&&<><div className="grid2"><label>Nombre<input required onChange={e=>setForm({...form,firstName:e.target.value})}/></label><label>Apellido<input required onChange={e=>setForm({...form,lastName:e.target.value})}/></label></div><label>WhatsApp<input required onChange={e=>setForm({...form,phone:e.target.value})}/></label><label>Circuito<select value={form.gender} onChange={e=>setForm({...form,gender:e.target.value})}><option value="male">Masculino</option><option value="female">Femenino</option></select></label><label>DNI (será tu usuario)<input required inputMode="numeric" onChange={e=>setForm({...form,dni:e.target.value})}/></label><div className="identity-upload"><b>Verificación de identidad</b><p>Subí una foto clara del frente y otra del dorso de tu DNI. Solo administración puede verlas y se purgan de la base activa cuando tu identidad se verifica o rechaza.</p><div className="grid2"><label>Frente del DNI<input required type="file" accept="image/jpeg,image/png,image/webp" capture="environment" onChange={e=>setForm({...form,dniFront:e.target.files?.[0]||null})}/></label><label>Dorso del DNI<input required type="file" accept="image/jpeg,image/png,image/webp" capture="environment" onChange={e=>setForm({...form,dniBack:e.target.files?.[0]||null})}/></label></div><small>Formatos: JPG, PNG o WEBP · máximo 5 MB por imagen.</small></div><div className="legal-box"><b>Antes de participar</b><p>Confirmás que sos mayor de 18 años, comprendés que el pádel implica riesgos físicos y aceptás las reglas, conducta, privacidad y comunicaciones operativas.</p><div className="legal-links"><a href="/legal/terms.md" target="_blank">Términos</a><a href="/legal/risks.md" target="_blank">Riesgos</a><a href="/legal/conduct.md" target="_blank">Conducta</a><a href="/legal/privacy.md" target="_blank">Privacidad</a><a href="/legal/whatsapp.md" target="_blank">WhatsApp</a></div><label className="check"><input type="checkbox" checked={acceptedLegal} onChange={e=>setAcceptedLegal(e.target.checked)}/><span>Confirmo que soy mayor de 18 años y acepto estos documentos.</span></label></div></>} {mode==='login'&&<label>DNI<input required inputMode="numeric" onChange={e=>setForm({...form,dni:e.target.value})}/></label>}<label>Contraseña<input required minLength="8" type="password" onChange={e=>setForm({...form,password:e.target.value})}/></label><button className="button primary" disabled={loading}>{loading?'Cargando...':'CONTINUAR'}</button></form><Notice n={notice}/><button className="link-button" type="button" onClick={()=>nav(mode==='login'?'/ingresar?registro=1':'/ingresar')}>{mode==='login'?'Crear una cuenta':'Ya tengo cuenta'}</button>{mode==='login'&&<Link className="link-button" to="/recuperar">Olvidé mi contraseña</Link>}</section></main></Layout>}

function AdminLogin(){const nav=useNavigate();const[form,setForm]=useState({}),[notice,setNotice]=useState(),[loading,setLoading]=useState(false);async function submit(e){e.preventDefault();try{setLoading(true);setNotice();const r=await api.post('/auth/admin-login',form);session(r.data);nav('/admin');}catch(e){setNotice({type:'error',text:'Acceso no autorizado.'});}finally{setLoading(false)}}return <div className="admin-login-shell"><main className="admin-login-wrap"><section className="admin-login-card"><div className="admin-login-brand"><span>LA RED</span><small>CONTROL</small></div><span className="eyebrow">ACCESO PRIVADO</span><h1>Administración</h1><p>Acceso reservado.</p><form onSubmit={submit}><label>DNI<input required autoComplete="username" inputMode="numeric" onChange={e=>setForm({...form,dni:e.target.value})}/></label><label>Contraseña<input required autoComplete="current-password" minLength="8" type="password" onChange={e=>setForm({...form,password:e.target.value})}/></label><label>Código de seguridad<input inputMode="numeric" autoComplete="one-time-code" placeholder="6 dígitos" onChange={e=>setForm({...form,totp:e.target.value})}/></label><button className="button primary" disabled={loading}>{loading?'Validando...':'INGRESAR'}</button></form><Notice n={notice}/></section></main></div>}

function Recovery(){const[dni,setDni]=useState(''),[code,setCode]=useState(''),[password,setPassword]=useState(''),[sent,setSent]=useState(false),[n,setN]=useState();async function request(){try{await api.post('/auth/recovery/request',{dni});setSent(true);setN({text:'Si el DNI existe, enviamos un código al WhatsApp registrado.'});}catch(e){setN({type:'error',text:err(e)})}}async function reset(){try{await api.post('/auth/recovery/reset',{dni,code,password});setN({text:'Contraseña actualizada. Ya podés ingresar.'});}catch(e){setN({type:'error',text:err(e)})}}return <Layout><main className="center"><section className="card auth"><h1>Recuperar acceso</h1><label>DNI<input value={dni} onChange={e=>setDni(e.target.value)}/></label>{!sent?<button className="button primary" onClick={request}>ENVIAR CÓDIGO</button>:<><label>Código<input value={code} onChange={e=>setCode(e.target.value)}/></label><label>Nueva contraseña<input type="password" minLength="8" value={password} onChange={e=>setPassword(e.target.value)}/></label><button className="button primary" onClick={reset}>CAMBIAR CONTRASEÑA</button></>}<Notice n={n}/></section></main></Layout>}
function Ranking(){const[rows,setRows]=useState([]),[slug,setSlug]=useState('masculino'),[cat,setCat]=useState(1);useEffect(()=>{api.get('/ranking').then(r=>setRows(r.data||[]))},[]);const filtered=rows.filter(r=>r.slug===slug&&Number(r.number)===Number(cat));return <Layout><main className="page ranking-page"><div className="page-title"><div><span className="eyebrow">LA RED</span><h1>Ranking</h1><p>La posición manda. El ELO acompaña.</p></div><div className="filters"><select value={slug} onChange={e=>setSlug(e.target.value)}><option>masculino</option><option>femenino</option></select><select value={cat} onChange={e=>setCat(e.target.value)}>{[1,2,3,4,5,6,7].map(n=><option key={n} value={n}>{n}ª</option>)}</select></div></div><div className="ranking"><div className="rank-head"><span>#</span><span>Pareja</span><span>ELO</span><span>PJ</span><span>PG</span><span>Games</span></div>{filtered.map(r=><Link to={`/parejas/${r.pair_id}`} className="rank-row" key={r.pair_id}><b>{r.position}</b><strong>{r.players}{r.competition_state==='paused'&&<small> · pausada</small>}</strong><span>{r.elo}</span><span>{r.played}</span><span>{r.wins}</span><span>{r.game_diff}</span></Link>)}</div><div className="help"><b>¿Cómo funciona?</b><p>Si una pareja ubicada más abajo vence a una que está arriba, intercambian posiciones. Las estadísticas no reordenan globalmente la escalera.</p></div></main></Layout>}
function PairProfile(){const{id}=useParams(),[d,setD]=useState();useEffect(()=>{api.get(`/pairs/${id}/profile`).then(r=>setD(r.data))},[id]);if(!d)return <Layout><main className="page">Cargando...</main></Layout>;return <Layout><main className="page pair-profile-page"><div className="page-title"><div><span className="eyebrow">PERFIL DEPORTIVO</span><h1>{d.pair.players}</h1><p>{d.pair.number}ª {d.pair.slug} · #{d.pair.position} · ELO {d.pair.elo}</p></div></div>{d.upcoming&&<article className="card featured-match-card"><span className="eyebrow">PRÓXIMO PARTIDO</span><h3>{fmt(d.upcoming.scheduled_at)} · {d.upcoming.venue_name}</h3></article>}<div className="grid3 profile-stats"><article className="card stat-card"><b>Partidos</b><h2>{d.pair.played}</h2></article><article className="card stat-card"><b>Victorias</b><h2>{d.pair.wins}</h2></article><article className="card stat-card"><b>Estado</b><h2>{d.pair.competition_state==='paused'?'Pausada':'Activa'}</h2></article></div><section className="page-section"><div className="section-heading"><div><span className="eyebrow">HISTORIAL</span><h2>Últimos resultados</h2></div></div><div className="stack">{d.matches.map(m=><article className="card compact" key={m.id}><b>{Number(m.winner_pair_id)===Number(id)?'Victoria':'Derrota'} · {m.result_type==='injury_abandonment'?'Lesión / abandono':'Resultado oficial'}</b><span>{fmt(m.played_at)}</span></article>)}{!d.matches.length&&<div className="empty">Todavía no hay resultados oficiales.</div>}</div></section><section className="page-section"><div className="section-heading"><div><span className="eyebrow">MOVIMIENTOS</span><h2>Historia competitiva</h2></div></div><div className="stack">{d.events.map((e,i)=><article className="card compact" key={i}><b>{eventText(e)}</b><span>{fmt(e.created_at)}</span></article>)}{!d.events.length&&<div className="empty">Todavía no hay movimientos competitivos.</div>}</div></section></main></Layout>}
function Upcoming(){const[rows,setRows]=useState([]),[slug,setSlug]=useState('todos'),[cat,setCat]=useState('todas'),[venue,setVenue]=useState('todos');useEffect(()=>{api.get('/upcoming').then(r=>setRows(r.data||[]))},[]);const venues=[...new Set(rows.map(r=>r.venue_name))].sort();const filtered=rows.filter(r=>(slug==='todos'||r.slug===slug)&&(cat==='todas'||Number(r.category_number)===Number(cat))&&(venue==='todos'||r.venue_name===venue));return <Layout><main className="page upcoming-page"><div className="page-title"><div><h1>Próximos partidos</h1><p>Solo aparecen programaciones aceptadas por ambas parejas.</p></div><div className="filters"><select value={slug} onChange={e=>setSlug(e.target.value)}><option value="todos">Todos</option><option value="masculino">Masculino</option><option value="femenino">Femenino</option></select><select value={cat} onChange={e=>setCat(e.target.value)}><option value="todas">Todas</option>{[1,2,3,4,5,6,7].map(n=><option key={n} value={n}>{n}ª</option>)}</select><select value={venue} onChange={e=>setVenue(e.target.value)}><option value="todos">Todos los lugares</option>{venues.map(v=><option key={v}>{v}</option>)}</select></div></div><div className="grid3 upcoming-grid">{filtered.map(r=><article className="card upcoming-card" key={r.id}><span className="eyebrow">{r.category_number}ª · {r.slug}</span><h3>{r.pair_a}<br/>vs.<br/>{r.pair_b}</h3><p>{fmt(r.scheduled_at)}<br/>{r.venue_name}</p></article>)}{!filtered.length&&<div className="empty">No hay partidos públicos que coincidan con estos filtros.</div>}</div></main></Layout>}
function PairManager(){const[d,setD]=useState(),[partner,setPartner]=useState(''),[cat,setCat]=useState(7),[n,setN]=useState();async function load(){try{setD((await api.get('/me/pair')).data)}catch(e){setN({type:'error',text:err(e)})}}useEffect(()=>{load()},[]);async function run(fn,msg){try{await fn();setN({text:msg});await load()}catch(e){setN({type:'error',text:err(e)})}}if(!d)return <Layout><main className="page">Cargando...</main></Layout>;return <Layout><main className="page pair-page"><div className="page-title pair-title"><div><span className="eyebrow">TU EQUIPO</span><h1>Mi pareja</h1><p>Formá tu equipo, aceptá invitaciones y administrá su estado competitivo.</p></div></div>{d.user.verification_status!=='verified'&&<div className="notice pair-verification-note">Tu identidad está pendiente de verificación. Podés recorrer LA RED, pero todavía no formar pareja ni competir.</div>}{d.pair?<><section className="page-section"><article className="card pair-current-card"><div><span className="eyebrow">{d.pair.category_number}ª · {d.pair.league_slug}</span><h2>{d.pair.members.map(m=>`${m.first_name} ${m.last_name}`).join(' / ')}</h2><p>Posición #{d.pair.position} · ELO {d.pair.elo} · {d.pair.competition_state}</p></div><div className="pair-state-badge">{d.pair.competition_state}</div></article><div className="actions pair-actions"><button className="button secondary" onClick={()=>run(()=>api.post('/me/pair/pause',{afterCurrent:true}),'Solicitud de pausa registrada.')}>PAUSAR AL TERMINAR</button><button className="button secondary" onClick={()=>run(()=>api.post('/me/pair/reactivate'),'Pareja reactivada.')}>REACTIVAR</button><button className="button danger" onClick={()=>confirm('¿Iniciar la disolución? Las obligaciones abiertas se resuelven antes de archivar la pareja.')&&run(()=>api.post('/me/pair/dissolve'),'Solicitud de disolución registrada.')}>DISOLVER</button></div></section></>:<><section className="pair-setup-grid"><article className="card form-card"><span className="eyebrow">FORMAR PAREJA</span><h2>Elegí compañero/a</h2><p className="card-intro">Solo aparecen jugadores verificados de tu mismo circuito que estén disponibles.</p><label>Jugador<select value={partner} onChange={e=>setPartner(e.target.value)}><option value="">Elegir jugador</option>{d.available.map(p=><option key={p.id} value={p.id}>{p.first_name} {p.last_name} · {p.current_category_number?`${p.current_category_number}ª`:'nuevo/a'}</option>)}</select></label><label>Categoría si ambos son nuevos<select value={cat} onChange={e=>setCat(e.target.value)}>{[1,2,3,4,5,6,7].map(x=><option key={x}>{x}</option>)}</select></label><button className="button primary" disabled={d.user.verification_status!=='verified'||!partner} onClick={()=>run(()=>api.post('/pair-invitations',{inviteeUserId:Number(partner),category:Number(cat)}),'Invitación enviada.')}>ENVIAR INVITACIÓN</button></article><aside className="card pair-guide-card"><span className="eyebrow">CÓMO SIGUE</span><div className="pair-guide-step"><b>01</b><div><strong>Invitación</strong><p>Elegís a otro jugador disponible.</p></div></div><div className="pair-guide-step"><b>02</b><div><strong>Aceptación</strong><p>La otra persona confirma desde su cuenta.</p></div></div><div className="pair-guide-step"><b>03</b><div><strong>Rueda</strong><p>LA RED crea la pareja y empieza a buscar rival.</p></div></div></aside></section><section className="page-section invitations-section"><div className="section-heading"><div><span className="eyebrow">PENDIENTES</span><h2>Invitaciones recibidas</h2></div><small>{d.incoming.length} pendientes</small></div><div className="stack">{d.incoming.map(i=><article className="card compact invitation-row" key={i.id}><div><b>{i.first_name} {i.last_name}</b><p>Pareja resultante en {i.resulting_category_number}ª</p></div><button onClick={()=>run(()=>api.patch(`/pair-invitations/${i.id}/accept`),'Pareja formada.')}>ACEPTAR</button></article>)}{!d.incoming.length&&<div className="empty">No tenés invitaciones pendientes.</div>}</div></section></>}<Notice n={n}/></main></Layout>}
function League(){const[d,setD]=useState(),[venues,setVenues]=useState([]),[n,setN]=useState(),[schedule,setSchedule]=useState({}),[result,setResult]=useState({resultType:'normal',sets:[{pairA:6,pairB:4,kind:'set'},{pairA:6,pairB:4,kind:'set'}]}),[report,setReport]=useState({target:'pair',reason:'misconduct',details:''});function setScore(i,key,value){setResult(r=>({...r,sets:r.sets.map((s,j)=>j===i?{...s,[key]:Number(value)}:s)}));}function addThird(){setResult(r=>({...r,sets:r.sets.length===3?r.sets:[...r.sets,{pairA:6,pairB:4,kind:'set'}]}));}function removeThird(){setResult(r=>({...r,sets:r.sets.slice(0,2)}));}async function load(){try{setD((await api.get('/me/league')).data);setVenues((await api.get('/venues')).data)}catch(e){setN({type:'error',text:err(e)})}}useEffect(()=>{load()},[]);async function run(fn,msg){try{await fn();setN({text:msg});await load()}catch(e){setN({type:'error',text:err(e)})}}if(!d)return <Layout><main className="page">Cargando...</main></Layout>;if(!d.pair){const pending=d.user?.verification_status==='pending';const resubmit=Boolean(d.user?.identity_resubmit_reason);const first=d.user?.first_name||user()?.first_name||'Jugador';return <Layout><main className="page league-onboarding-page"><section className="league-onboarding-hero"><div className="league-onboarding-copy"><span className="eyebrow">MI LIGA · PRIMEROS PASOS</span><h1>{resubmit?'Necesitamos una nueva foto de tu DNI.':pending?`Bienvenido a LA RED, ${first}.`:'Tu liga empieza acá.'}</h1><p className="lead">{resubmit?`Administración no pudo validar las imágenes anteriores. Motivo: ${d.user.identity_resubmit_reason}`:pending?'Tu cuenta ya está creada y tu identidad está en revisión. Mientras tanto podés conocer el ranking y la cartelera; no corre ningún plazo deportivo.':'Tu identidad ya está verificada. El próximo paso es formar tu pareja y entrar a la rueda automática.'}</p><div className="actions">{pending?<><Link className="button button-green" to="/cuenta">{resubmit?'REENVIAR DOCUMENTACIÓN':'VER MI CUENTA'}</Link><Link className="button button-outline" to="/ranking">RECORRER RANKING</Link></>:<><Link className="button button-green" to="/pareja">FORMAR MI PAREJA</Link><Link className="button button-outline" to="/ranking">VER RANKING</Link></>}</div></div><aside className={`league-account-status ${resubmit?'is-resubmit':pending?'is-pending':'is-ready'}`}><span className="league-status-kicker">ESTADO DE TU CUENTA</span><div className="league-status-icon">{resubmit?'!':pending?'◷':'✓'}</div><strong>{resubmit?'FOTOS A REENVIAR':pending?'IDENTIDAD EN REVISIÓN':'IDENTIDAD VERIFICADA'}</strong><p>{resubmit?d.user.identity_resubmit_reason:pending?'Administración está revisando tu documentación. Si notás que subiste mal una foto, podés reemplazarla desde Mi cuenta.':'Ya podés formar pareja con otro jugador verificado de tu circuito.'}</p><div className="league-status-meta"><span><small>PAREJA</small><b>Pendiente</b></span><span><small>PLAZOS ACTIVOS</small><b>0</b></span></div></aside></section><section className="league-progress"><article className="league-step done"><span>01</span><div><small>LISTO</small><h3>Cuenta creada</h3><p>Tu acceso ya está activo.</p></div></article><article className={`league-step ${pending?'active':'done'}`}><span>02</span><div><small>{resubmit?'ACCIÓN REQUERIDA':pending?'AHORA':'LISTO'}</small><h3>Verificación</h3><p>{resubmit?'Reenviá frente y dorso para continuar.':pending?'Estamos comprobando tu identidad.':'Identidad confirmada.'}</p></div></article><article className={`league-step ${pending?'locked':'active'}`}><span>03</span><div><small>{pending?'DESPUÉS':'SIGUIENTE'}</small><h3>Formar pareja</h3><p>Invitación + aceptación entre dos jugadores.</p></div></article><article className="league-step locked"><span>04</span><div><small>DESPUÉS</small><h3>Entrar a la rueda</h3><p>LA RED te asigna rival automáticamente.</p></div></article></section><section className="grid3 league-onboarding-info"><article className="card"><span className="eyebrow">SIN PRESIÓN</span><h3>No hay reloj corriendo</h3><p>Hasta que exista un partido asignado, no hay vencimientos ni sanciones por inactividad.</p></article><article className="card"><span className="eyebrow">PRIVACIDAD</span><h3>Tu identidad es privada</h3><p>Ranking, perfiles y próximos partidos no muestran DNI ni WhatsApp.</p></article><article className="card"><span className="eyebrow">AUTOMÁTICO</span><h3>Después trabaja la rueda</h3><p>Con la pareja lista, LA RED busca rival y te muestra siempre qué acción sigue.</p></article></section></main></Layout>}const a=d.assignment;return <Layout><main className="page league-page"><span className="eyebrow">¿QUÉ TE TOCA HACER AHORA?</span><h1>{!a?'Estás al día':a.status==='result_pending'&&!a.myVersion?'Confirmar resultado':a.status==='disputed'?'Esperar resolución':a.schedule_confirmed_at?'Jugar / cargar resultado':'Coordinar el partido'}</h1><p className="lead">{d.pair.players} · {d.pair.category_number}ª · #{d.pair.position} · ELO {d.pair.elo}</p>{a?<div className="grid2"><article className="card"><span className="eyebrow">PARTIDO ACTUAL</span><h2>vs. {a.rival.players}</h2><p>Vence: {fmt(a.extraordinary_deadline_at||a.deadline_at)}</p>{a.schedule_confirmed_at&&<p><b>Oficial:</b> {fmt(a.scheduled_at)}</p>}<div className="actions">{a.rival.members.map(m=><a className="button secondary" key={m.id} href={`https://wa.me/${String(m.phone||'').replace(/\D/g,'')}`} target="_blank">WHATSAPP · {m.first_name}</a>)}</div>{a.pendingProposal&&<><p>Propuesta pendiente: {fmt(a.pendingProposal.scheduled_at)} · {a.pendingProposal.venue_name}</p>{Number(a.pendingProposal.proposed_by_pair_id)!==Number(d.pair.id)&&<button onClick={()=>run(()=>api.patch(`/assignments/${a.id}/schedule-proposals/${a.pendingProposal.id}/accept`),'Programación confirmada.')}>ACEPTAR PROPUESTA</button>}</>}</article><article className="card"><h2>Proponer fecha</h2><label>Día y hora<input type="datetime-local" onChange={e=>setSchedule({...schedule,scheduledAt:e.target.value})}/></label><label>Lugar<select onChange={e=>setSchedule({...schedule,venueId:Number(e.target.value)})}><option>Elegir</option>{venues.map(v=><option key={v.id} value={v.id}>{v.name}</option>)}</select></label><button onClick={()=>run(()=>api.post(`/assignments/${a.id}/schedule-proposals`,schedule),'Propuesta enviada.')}>PROPONER</button><button className="secondary" onClick={()=>run(()=>api.post(`/assignments/${a.id}/extension-vote`),'Confirmación de causa externa registrada.')}>CAUSA EXTERNA</button></article><article className="card"><h2>Resultado</h2>{a.otherVersion&&!a.myVersion?<button className="button primary" onClick={()=>run(()=>api.patch(`/assignments/${a.id}/results/confirm`),'Resultado confirmado.')}>CONFIRMAR RESULTADO CARGADO</button>:<><label>Tipo<select value={result.resultType} onChange={e=>setResult({...result,resultType:e.target.value})}><option value="normal">Normal</option><option value="injury_abandonment">Lesión / abandono</option></select></label><label>Ganador<select onChange={e=>setResult({...result,winnerPairId:Number(e.target.value)})}><option>Elegir</option><option value={d.pair.id}>Mi pareja</option><option value={a.rival.id}>{a.rival.players}</option></select></label><label>Fecha jugada<input type="date" onChange={e=>setResult({...result,playedAt:`${e.target.value}T12:00:00-03:00`})}/></label>{result.resultType==='normal'&&<div className="score-box"><b>Marcador</b><small>Columna A = pareja #{a.pair_a_id} · Columna B = pareja #{a.pair_b_id}</small>{result.sets.map((set,i)=><div className="score-row" key={i}><span>{i+1}º</span><input type="number" min="0" value={set.pairA} onChange={e=>setScore(i,'pairA',e.target.value)}/><input type="number" min="0" value={set.pairB} onChange={e=>setScore(i,'pairB',e.target.value)}/>{i===2&&<select value={set.kind} onChange={e=>setResult(r=>({...r,sets:r.sets.map((x,j)=>j===2?{...x,kind:e.target.value}:x)}))}><option value="set">Set</option><option value="match_tiebreak">Super tie-break</option></select>}</div>)}{result.sets.length===2?<button type="button" className="secondary" onClick={addThird}>AGREGAR TERCER PARCIAL</button>:<button type="button" className="secondary" onClick={removeThird}>QUITAR TERCER PARCIAL</button>}</div>}{result.resultType==='injury_abandonment'&&<label>Abandonó<select onChange={e=>setResult({...result,abandonedPairId:Number(e.target.value)})}><option>Elegir</option><option value={d.pair.id}>Mi pareja</option><option value={a.rival.id}>{a.rival.players}</option></select></label>}<button className="button primary" onClick={()=>run(()=>api.post(`/assignments/${a.id}/results`,{...result,score:result.resultType==='normal'?{sets:result.sets}:null}),'Resultado cargado.')}>CARGAR RESULTADO</button></>}</article><article className="card"><h2>Incidentes</h2>{a.schedule_confirmed_at&&<button className="button secondary" onClick={()=>run(()=>api.post(`/assignments/${a.id}/no-show`),'No-show informado. El rival tiene 48 h para objetar.')}>REPORTAR NO-SHOW</button>}{a.noShow&&Number(a.noShow.reported_pair_id)===Number(d.pair.id)&&a.noShow.status==='pending'&&<button className="button secondary" onClick={()=>run(()=>api.patch(`/assignments/${a.id}/no-show/contest`),'No-show objetado.')}>OBJETAR NO-SHOW</button>}<hr/><label>Reportar a<select value={report.target} onChange={e=>setReport({...report,target:e.target.value})}><option value="pair">Pareja rival</option>{a.rival.members.map(m=><option key={m.id} value={`user:${m.id}`}>{m.first_name} {m.last_name}</option>)}</select></label><label>Motivo<select value={report.reason} onChange={e=>setReport({...report,reason:e.target.value})}><option value="misconduct">Mala conducta</option><option value="violence">Violencia</option><option value="threats">Amenazas</option><option value="coordination_refusal">Negativa a coordinar</option><option value="other">Otro</option></select></label><label>Detalle<textarea value={report.details} onChange={e=>setReport({...report,details:e.target.value})}/></label><button onClick={()=>run(()=>api.post('/discipline-reports',{assignmentId:a.id,...(String(report.target).startsWith('user:')?{targetUserId:Number(report.target.split(':')[1])}:{targetPairId:a.rival.id}),reason:report.reason,details:report.details}),'Reporte disciplinario registrado.')}>ENVIAR REPORTE</button></article></div>:<div className="empty">La rueda está buscando tu próximo rival. No corre ningún plazo hasta que exista una asignación.</div>}<Notice n={n}/><section><h2>Qué acaba de pasar</h2><div className="stack">{d.recentEvents.map((e,i)=><article className="card compact" key={i}><b>{eventText(e)}</b><span>{fmt(e.created_at)}</span></article>)}</div></section></main></Layout>}
function Notifications(){const[rows,setRows]=useState([]);async function load(){setRows((await api.get('/me/notifications')).data||[])}useEffect(()=>{load()},[]);return <Layout><main className="page notifications-page"><div className="page-title"><div><span className="eyebrow">CENTRO DE AVISOS</span><h1>Avisos</h1><p>Todo lo importante de tu actividad queda guardado acá, aunque también llegue por WhatsApp.</p></div><div className="notification-counter"><strong>{rows.filter(n=>!n.read_at).length}</strong><span>sin leer</span></div></div><div className="stack notifications-stack">{rows.map(n=><article className={`card compact notification-row ${n.read_at?'read':'unread'}`} key={n.id} onClick={()=>!n.read_at&&api.patch(`/me/notifications/${n.id}/read`).then(load)}><div><span className="notification-dot"/><div><b>{n.title}</b><p>{n.body}</p></div></div><small>{fmt(n.created_at)}</small></article>)}{!rows.length&&<div className="empty">Todavía no tenés avisos. Cuando LA RED necesite algo de vos, va a aparecer acá.</div>}</div></main></Layout>}
function Account(){const[u,setU]=useState(),[phone,setPhone]=useState(''),[code,setCode]=useState(''),[n,setN]=useState(),[sent,setSent]=useState(false),[docs,setDocs]=useState({front:null,back:null}),[uploadingDocs,setUploadingDocs]=useState(false),[docsKey,setDocsKey]=useState(0);async function load(){try{setU((await api.get('/me')).data)}catch(e){setN({type:'error',text:err(e)})}}useEffect(()=>{load()},[]);async function request(){try{await api.post('/me/phone/request',{phone});setSent(true);setN({text:'Enviamos un código al nuevo WhatsApp.'})}catch(e){setN({type:'error',text:err(e)})}}async function confirmPhone(){try{await api.post('/me/phone/confirm',{code});setN({text:'WhatsApp actualizado y auditado.'});setSent(false);setPhone('');setCode('');await load()}catch(e){setN({type:'error',text:err(e)})}}async function resendIdentity(){if(!docs.front||!docs.back){setN({type:'error',text:'Elegí una foto del frente y otra del dorso.'});return;}try{setUploadingDocs(true);const data=new FormData();data.append('dniFront',docs.front);data.append('dniBack',docs.back);await api.post('/me/identity-documents',data);setDocs({front:null,back:null});setDocsKey(k=>k+1);setN({text:'Recibimos las nuevas fotos. Tu identidad volvió a quedar lista para revisión.'});await load()}catch(e){setN({type:'error',text:err(e)})}finally{setUploadingDocs(false)}}return <Layout><main className="page account-page"><div className="page-title"><div><span className="eyebrow">PERFIL Y SEGURIDAD</span><h1>Mi cuenta</h1><p>Tus datos privados, estado de identidad y canales de contacto.</p></div></div><div className="account-grid">{u&&<article className="card account-profile-card"><div className="account-person"><span>{[u.first_name,u.last_name].filter(Boolean).map(v=>v[0]).join('').slice(0,2).toUpperCase()}</span><div><small>JUGADOR</small><h2>{u.first_name} {u.last_name}</h2></div></div><div className="account-meta"><div><small>IDENTIDAD</small><strong>{u.verification_status==='verified'?'Verificada':'Pendiente'}</strong></div><div><small>CATEGORÍA INDIVIDUAL</small><strong>{u.current_category_number?`${u.current_category_number}ª`:'Sin categoría'}</strong></div></div><p className="privacy-note">Tu DNI y tu teléfono no aparecen en perfiles públicos ni ranking.</p></article>}<article className="card account-security-card"><span className="eyebrow">SEGURIDAD</span><h2>Cambiar WhatsApp</h2><p className="card-intro">El número nuevo se confirma con un código antes de reemplazar el actual.</p><label>Nuevo número<input value={phone} onChange={e=>setPhone(e.target.value)} placeholder="Ej. 3329..."/></label><button onClick={request}>ENVIAR CÓDIGO</button>{sent&&<div className="phone-confirm-box"><label>Código<input value={code} onChange={e=>setCode(e.target.value)}/></label><button className="button primary" onClick={confirmPhone}>CONFIRMAR CAMBIO</button></div>}</article></div>{u?.verification_status==='pending'&&<section className={`card identity-resubmit-card ${u.identity_resubmit_reason?'needs-resubmit':''}`}><span className="eyebrow">{u.identity_resubmit_reason?'ACCIÓN REQUERIDA':'VERIFICACIÓN DE IDENTIDAD'}</span><h2>{u.identity_resubmit_reason?'Necesitamos nuevas fotos de tu DNI':'¿Subiste una foto incorrecta?'}</h2><p>{u.identity_resubmit_reason?<>Administración pidió que vuelvas a enviar frente y dorso. <b>Motivo:</b> {u.identity_resubmit_reason}</>:<>Mientras tu identidad siga pendiente podés reemplazar el frente y dorso sin crear otra cuenta. Las nuevas fotos reemplazan las anteriores.</>}</p><div className="identity-resubmit-grid" key={docsKey}><label>Nuevo frente<input type="file" accept="image/jpeg,image/png,image/webp" capture="environment" onChange={e=>setDocs(d=>({...d,front:e.target.files?.[0]||null}))}/></label><label>Nuevo dorso<input type="file" accept="image/jpeg,image/png,image/webp" capture="environment" onChange={e=>setDocs(d=>({...d,back:e.target.files?.[0]||null}))}/></label></div><div className="identity-resubmit-actions"><button className="button primary" disabled={uploadingDocs} onClick={resendIdentity}>{uploadingDocs?'ENVIANDO...':'REENVIAR FRENTE Y DORSO'}</button><small>JPG, PNG o WEBP · máximo 5 MB por imagen.</small></div></section>}<Notice n={n}/></main></Layout>}

async function openIdentityDocument(userId,side){const r=await api.get(`/admin/identity/${userId}/document/${side}`,{responseType:'blob'});const url=URL.createObjectURL(r.data);const w=window.open(url,'_blank','noopener,noreferrer');if(!w)throw new Error('El navegador bloqueó la apertura de la imagen.');setTimeout(()=>URL.revokeObjectURL(url),60000);}
function Admin(){const[status,setStatus]=useState(),[pending,setPending]=useState([]),[venues,setVenues]=useState([]),[disputes,setDisputes]=useState([]),[discipline,setDiscipline]=useState([]),[audit,setAudit]=useState([]),[search,setSearch]=useState(''),[users,setUsers]=useState([]),[venue,setVenue]=useState({active:true}),[n,setN]=useState();async function load(reportError=true){try{const[s,p,v,d,r,a]=await Promise.all([api.get('/admin/status'),api.get('/admin/identity/pending'),api.get('/admin/venues'),api.get('/admin/disputes'),api.get('/admin/discipline'),api.get('/admin/audit',{params:{limit:80}})]);setStatus(s.data);setPending(p.data);setVenues(v.data);setDisputes(d.data);setDiscipline(r.data);setAudit(a.data);return true}catch(e){if(reportError)setN({type:'error',text:err(e)});return false}}useEffect(()=>{load()},[]);async function run(fn,msg){try{await fn();const refreshed=await load(false);setN({text:refreshed?msg:`${msg} El panel no pudo refrescarse automáticamente; recargá la página.`})}catch(e){setN({type:'error',text:err(e)})}}async function find(){try{setUsers((await api.get('/admin/identity/search',{params:{q:search}})).data)}catch(e){setN({type:'error',text:err(e)})}}return <Layout><main className="page admin-page"><span className="eyebrow">ADMINISTRACIÓN</span><h1>{(status?.disputes||0)+(status?.pendingIdentity||0)+(status?.discipline||0)===0?'Todo funcionando normalmente':'Hay excepciones para revisar'}</h1><p className="lead">El motor resuelve lo determinístico. Acá aparecen solamente identidad, disputas reales, disciplina, canchas, correcciones y salud del sistema.</p><div className="admin-summary"><article className="card"><span>IDENTIDAD</span><strong>{status?.pendingIdentity??'-'}</strong><small>pendientes</small></article><article className="card"><span>DISPUTAS</span><strong>{status?.disputes??'-'}</strong><small>resultados</small></article><article className="card"><span>DISCIPLINA</span><strong>{status?.discipline??'-'}</strong><small>casos abiertos</small></article><article className="card"><span>RUEDA</span><strong>{status?.openAssignments??'-'}</strong><small>partidos abiertos</small></article><article className="card"><span>WHATSAPP</span><strong>{status?.whatsapp?'OK':'—'}</strong><small>{status?.outboxFailed?`${status.outboxFailed} fallidos`:status?.whatsapp?'operativo':'sin configurar'}</small></article><article className="card"><span>RELOJES</span><strong>{status?.clockPaused?'PAUSA':'OK'}</strong><small>{status?.clockPaused?'suspendidos':'corriendo'}</small></article></div><div className="actions"><button className="button secondary" onClick={()=>run(()=>api.post('/admin/maintenance'),'Mantenimiento ejecutado.')}>EJECUTAR MANTENIMIENTO</button><button className="button secondary" onClick={()=>run(()=>api.post('/admin/whatsapp/retry'),'Outbox de WhatsApp procesada.')}>REINTENTAR WHATSAPP</button><button className="button danger" onClick={()=>confirm('¿Suspender todos los relojes de la liga?')&&run(()=>api.patch('/admin/system/clock',{paused:true}),'Relojes suspendidos.')}>SUSPENDER RELOJES</button><button className="button secondary" onClick={()=>confirm('¿Reanudar los relojes y extender automáticamente los plazos por el tiempo suspendido?')&&run(()=>api.patch('/admin/system/clock',{paused:false}),'Relojes reanudados.')}>REANUDAR RELOJES</button></div><Notice n={n}/><section><h2>Identidad pendiente</h2>{pending.map(u=><article className="card identity-review" key={u.id}><div><b>{u.first_name} {u.last_name}</b><p>DNI {u.dni} · {u.phone}</p><small>{u.identity_resubmit_reason?`Esperando nuevas fotos · ${u.identity_resubmit_reason}`:u.documents_available?'Frente y dorso disponibles para revisión.':'Faltan documentos de identidad.'}</small></div><div className="identity-doc-actions"><button className="secondary" disabled={!u.documents_available} onClick={()=>openIdentityDocument(u.id,'front').catch(e=>setN({type:'error',text:err(e)}))}>VER FRENTE</button><button className="secondary" disabled={!u.documents_available} onClick={()=>openIdentityDocument(u.id,'back').catch(e=>setN({type:'error',text:err(e)}))}>VER DORSO</button><button className="secondary" onClick={()=>{const reason=window.prompt('Motivo para pedir nuevas fotos (ej: frente borroso, dorso cortado):',u.identity_resubmit_reason||'');if(reason?.trim())run(()=>api.post(`/admin/identity/${u.id}/resubmit`,{reason:reason.trim()}),'Se pidieron nuevas fotos. El jugador fue avisado.')}}>PEDIR NUEVAS FOTOS</button><button disabled={!u.documents_available} onClick={()=>confirm('¿Confirmás que nombre, foto y DNI corresponden a esta persona? Al verificar, las imágenes del DNI se purgan de la base activa.')&&run(()=>api.patch(`/admin/identity/${u.id}`,{status:'verified'}),'Jugador verificado; las imágenes del DNI fueron purgadas de la base activa.')}>VERIFICAR</button><button className="danger" onClick={()=>confirm('Usá RECHAZAR CUENTA solo si la identidad no corresponde o la cuenta no debe habilitarse. ¿Continuar?')&&run(()=>api.patch(`/admin/identity/${u.id}`,{status:'rejected'}),'Cuenta rechazada y documentos purgados de la base activa.')}>RECHAZAR CUENTA</button></div></article>)}{!pending.length&&<div className="empty">No hay identidades pendientes.</div>}</section><section><h2>Buscar / corregir DNI</h2><div className="inline"><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Nombre o DNI"/><button onClick={find}>BUSCAR</button></div>{users.map(u=><IdentityRow key={u.id} u={u} done={load}/>)}</section><section><h2>Disputas reales</h2>{disputes.map(d=><article className="card" key={d.id}><b>Partido #{d.id}</b>{d.versions.map(v=><div className="card compact" key={v.id}><span>Versión pareja #{v.pair_id} · ganador #{v.winner_pair_id}</span><button onClick={()=>confirm('Esta resolución puede mover ranking y rachas. ¿Confirmar?')&&run(()=>api.patch(`/admin/disputes/${d.id}`,{action:'select',versionId:v.id}),'Disputa resuelta.')}>VALIDAR ESTA</button></div>)}<button className="danger" onClick={()=>confirm('¿Cerrar sin resultado oficial?')&&run(()=>api.patch(`/admin/disputes/${d.id}`,{action:'void'}),'Partido cerrado void.')}>RECHAZAR AMBAS</button></article>)}{!disputes.length&&<div className="empty">No hay disputas reales pendientes.</div>}</section><section><h2>Disciplina</h2>{discipline.map(r=><article className="card compact" key={r.id}><div><b>{r.reason}</b><p>{r.details}</p></div><div><button onClick={()=>run(()=>api.patch(`/admin/discipline/${r.id}`,{status:'reviewed'}),'Marcado revisado.')}>REVISADA</button><button onClick={()=>run(()=>api.patch(`/admin/discipline/${r.id}`,{status:'dismissed'}),'Descartada.')}>DESCARTAR</button><button onClick={()=>run(()=>api.patch(`/admin/discipline/${r.id}`,{status:'resolved'}),'Disciplina resuelta.')}>RESOLVER</button></div></article>)}{!discipline.length&&<div className="empty">No hay casos disciplinarios pendientes.</div>}</section><section><h2>Canchas</h2><article className="card"><div className="grid2"><label>Nombre<input onChange={e=>setVenue({...venue,name:e.target.value})}/></label><label>Dirección<input onChange={e=>setVenue({...venue,address:e.target.value})}/></label><label className="check"><input type="checkbox" checked={Boolean(venue.associated)} onChange={e=>setVenue({...venue,associated:e.target.checked})}/><span>Sede asociada / recomendada</span></label><label className="check"><input type="checkbox" checked={Boolean(venue.bookingEnabled)} onChange={e=>setVenue({...venue,bookingEnabled:e.target.checked})}/><span>Preparada para reservas futuras</span></label></div><button onClick={()=>run(()=>api.post('/admin/venues',venue),'Cancha creada.')}>AGREGAR CANCHA</button></article>{venues.map(v=><article className="card compact" key={v.id}><div><b>{v.name}</b><p>{v.address} · {v.active?'Activa':'Inactiva'}</p></div><button onClick={()=>run(()=>api.patch(`/admin/venues/${v.id}`,{active:!v.active}),v.active?'Cancha desactivada.':'Cancha activada.')}>{v.active?'DESACTIVAR':'ACTIVAR'}</button></article>)}</section><section><h2>Auditoría administrativa</h2><p className="muted">Las decisiones sensibles no se borran: queda quién hizo qué, cuándo y sobre qué objeto.</p><div className="stack">{audit.map(e=><article className="audit-row" key={e.id}><div><b>{e.action}</b><span>{e.target_type}{e.target_id?` #${e.target_id}`:''}</span></div><div><small>{e.admin_name}</small><small>{fmt(e.created_at)}</small></div></article>)}{!audit.length&&<div className="empty">Todavía no hay acciones administrativas auditadas.</div>}</div></section></main></Layout>}
function IdentityRow({u,done}){const[dni,setDni]=useState(u.dni),[n,setN]=useState();async function save(){if(!confirm(`Corregir DNI de ${u.first_name} ${u.last_name} a ${dni}?`))return;try{await api.patch(`/admin/identity/${u.id}/dni`,{dni});setN({text:'Corregido y auditado.'});done()}catch(e){setN({type:'error',text:err(e)})}}return <article className="card compact"><div><b>{u.first_name} {u.last_name}</b><p>{u.phone} · {u.verification_status}</p></div><div className="inline"><input value={dni} onChange={e=>setDni(e.target.value)}/><button onClick={save}>CORREGIR DNI</button></div><Notice n={n}/></article>}
function Install(){return <Layout><main className="page install-page"><div className="page-title"><div><span className="eyebrow">PWA · MÓVIL</span><h1>Instalar LA RED</h1><p>Usá la misma liga desde el navegador o agregala a la pantalla de inicio como una app.</p></div></div><div className="grid3 install-grid"><article className="card"><span className="install-step">01</span><h2>Abrí LA RED</h2><p>Entrá desde Safari en iPhone o Chrome en Android.</p></article><article className="card"><span className="install-step">02</span><h2>Agregar a inicio</h2><p>Usá la opción “Agregar a pantalla de inicio” o “Instalar aplicación”.</p></article><article className="card"><span className="install-step">03</span><h2>Entrá normalmente</h2><p>Tu cuenta, ranking, pareja y rueda son exactamente los mismos.</p></article></div></main></Layout>}
function Protected({children,adminOnly=false}){const u=user();if(!u)return <Auth/>;if(adminOnly&&u.role!=='admin')return <Layout><main className="page"><div className="empty">Acceso restringido.</div></main></Layout>;return children;}
export default function App(){return <Routes><Route path="/" element={<Home/>}/><Route path="/ingresar" element={<Auth/>}/><Route path="/admin-la-red" element={<AdminLogin/>}/><Route path="/recuperar" element={<Recovery/>}/><Route path="/ranking" element={<Ranking/>}/><Route path="/proximos" element={<Upcoming/>}/><Route path="/parejas/:id" element={<PairProfile/>}/><Route path="/instalar" element={<Install/>}/><Route path="/liga" element={<Protected><League/></Protected>}/><Route path="/pareja" element={<Protected><PairManager/></Protected>}/><Route path="/notificaciones" element={<Protected><Notifications/></Protected>}/><Route path="/cuenta" element={<Protected><Account/></Protected>}/><Route path="/admin" element={<Protected adminOnly><Admin/></Protected>}/><Route path="*" element={<Home/>}/></Routes>}
